#[cfg(test)]
mod tests {
    #[test]
    #[ignore = "TODO: empty item list -> premium 5 G (processing fee only)"]
    fn quote_for_empty_item_list_is_only_the_processing_fee() {}

    #[test]
    #[ignore = "TODO: sword alone -> base 100 G + 10 G first insurance + 5 G fee = 115 G"]
    fn quote_for_a_plain_sword_uses_the_sword_base_premium() {}

    #[test]
    #[ignore = "TODO: amulet alone -> base 60 G + 6 G first insurance + 5 G fee = 71 G"]
    fn quote_for_a_plain_amulet_uses_the_amulet_base_premium() {}

    #[test]
    #[ignore = "TODO: staff alone -> base 80 G + 8 G first insurance + 5 G fee = 93 G"]
    fn quote_for_a_plain_staff_uses_the_staff_base_premium() {}

    #[test]
    #[ignore = "TODO: potion alone -> base 40 G + 4 G first insurance + 5 G fee = 49 G"]
    fn quote_for_a_plain_potion_uses_the_potion_base_premium() {}

    #[test]
    #[ignore = "TODO: single rune -> base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)"]
    fn quote_for_a_single_rune_uses_the_component_base_premium() {}

    #[test]
    #[ignore = "TODO: single moonstone -> base 25 G, same component price list entry as a rune"]
    fn quote_for_a_single_moonstone_uses_the_component_base_premium() {}

    #[test]
    #[ignore = "TODO: unknown item type 'broomstick' in a quote -> Err from the library; CLI exits non-zero"]
    fn quote_with_an_unknown_item_type_is_rejected() {}

    #[test]
    #[ignore = "TODO: 2 runes -> 50 G base premium (no block)"]
    fn two_alike_components_have_no_block_discount() {}

    #[test]
    #[ignore = "TODO: 3 runes -> 60 G base premium (block applies)"]
    fn three_alike_components_form_a_block_at_sixty() {}

    #[test]
    #[ignore = "TODO: 4 runes -> 100 G base premium (block requires exactly 3)"]
    fn four_alike_components_get_no_block_discount() {}

    #[test]
    #[ignore = "TODO: 7 runes -> 175 G base premium"]
    fn seven_alike_components_get_no_block_discount() {}

    #[test]
    #[ignore = "TODO: 2 runes + 1 moonstone -> 75 G base premium (different types, no block)"]
    fn components_of_different_types_do_not_form_a_block() {}

    #[test]
    #[ignore = "TODO: 3 runes + 3 moonstones -> 120 G base premium (two separate blocks)"]
    fn each_component_type_forms_its_own_block() {}

    #[test]
    #[ignore = "TODO: cursed sword adds 50 G (50% of the sword base premium)"]
    fn a_cursed_item_adds_a_fifty_percent_risk_surcharge() {}

    #[test]
    #[ignore = "TODO: sword with enchantment 5 adds 30 G high-enchantment surcharge (threshold inclusive)"]
    fn enchantment_of_exactly_five_adds_the_high_enchantment_surcharge() {}

    #[test]
    #[ignore = "TODO: sword with enchantment 4 adds no high-enchantment surcharge"]
    fn enchantment_of_four_adds_no_high_enchantment_surcharge() {}

    #[test]
    #[ignore = "TODO: cursed sword with enchantment 5 adds both surcharges (50 G + 30 G)"]
    fn cursed_and_highly_enchanted_item_gets_both_surcharges() {}

    #[test]
    #[ignore = "TODO: customer with exactly 2 years gets the 20% loyalty discount"]
    fn exactly_two_years_with_mhpco_grants_the_loyalty_discount() {}

    #[test]
    #[ignore = "TODO: customer with 1 year gets no loyalty discount"]
    fn one_year_with_mhpco_grants_no_loyalty_discount() {}

    #[test]
    #[ignore = "TODO: second quote in a scenario gets the 15% follow-up contract discount"]
    fn a_follow_up_contract_gets_the_fifteen_percent_discount() {}

    #[test]
    #[ignore = "TODO: first insurance surcharge applies per item even on a follow-up contract"]
    fn the_first_insurance_surcharge_applies_to_every_quoted_item() {}

    #[test]
    #[ignore = "TODO: cursed sword 100 G + plain amulet 60 G -> 160 G base, curse adds 50 G -> 210 G before policy modifiers and fee"]
    fn an_item_surcharge_applies_only_to_the_affected_items_base_premium() {}

    #[test]
    #[ignore = "TODO: a premium yielding 197.5 G rounds up to 198 G (MHPCO's favor)"]
    fn a_fractional_premium_is_rounded_up() {}

    #[test]
    #[ignore = "TODO: newcomer with a cursed sword -> premium 165 G"]
    fn integration_newcomer_with_a_cursed_sword_pays_165() {}

    #[test]
    #[ignore = "TODO: long-standing customer's second contract, cursed sword enchantment 7 -> premium 160 G"]
    fn integration_long_standing_customers_second_contract_pays_160() {}

    #[test]
    #[ignore = "TODO: steel sword enchantment 3, damage 500 G -> payout 400 G"]
    fn standard_damage_is_reimbursed_in_full_minus_the_deductible() {}

    #[test]
    #[ignore = "TODO: rune damage 200 G -> payout 100 G (no enchantment or material, no special clause)"]
    fn component_damage_is_reimbursed_in_full_minus_the_deductible() {}

    #[test]
    #[ignore = "TODO: steel sword enchantment 9, damage 1000 G -> payout 400 G (50% then deductible)"]
    fn damage_to_a_highly_enchanted_item_is_halved_before_the_deductible() {}

    #[test]
    #[ignore = "TODO: steel sword enchantment 8, damage 1000 G -> payout 400 G (threshold 8 inclusive)"]
    fn enchantment_of_exactly_eight_triggers_the_half_reimbursement() {}

    #[test]
    #[ignore = "TODO: dragon sword enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)"]
    fn dragon_material_damage_is_fully_reimbursed_minus_the_deductible() {}

    #[test]
    #[ignore = "TODO: dragon sword enchantment 9, damage 1000 G -> payout 400 G (the 50% rule wins)"]
    fn the_high_enchantment_clause_wins_over_dragon_material() {}

    #[test]
    #[ignore = "TODO: dragon sword enchantment 8, damage 1000 G -> payout 400 G"]
    fn dragon_material_with_enchantment_exactly_eight_pays_400() {}

    #[test]
    #[ignore = "TODO: sword 500 G and amulet 300 G in one incident -> payout 600 G (deductible per damaged item)"]
    fn the_deductible_applies_once_per_damaged_item() {}

    #[test]
    #[ignore = "TODO: a payout yielding 350.5 G rounds down to 350 G (MHPCO's favor)"]
    fn a_fractional_payout_is_rounded_down() {}

    #[test]
    #[ignore = "TODO: policy over a sword and an amulet -> insurance sum 1600 G, cap 3200 G"]
    fn the_cap_is_twice_the_sum_of_the_insured_items_values() {}

    #[test]
    #[ignore = "TODO: cursed sword -> cap 2000 G; premium modifiers do not raise the cap"]
    fn premium_modifiers_do_not_change_the_cap() {}

    #[test]
    #[ignore = "TODO: policy over a sword and 3 runes -> insurance sum 1750 G; the block discount does not change the sum"]
    fn the_block_discount_does_not_change_the_insurance_sum() {}

    #[test]
    #[ignore = "TODO: sword, cap 2000 G, two claims of 1500 G -> payouts 1400 G then 600 G, remaining cap 600 G then 0 G"]
    fn successive_claims_exhaust_the_remaining_cap() {}

    #[test]
    #[ignore = "TODO: policy over two swords -> insurance sum 2000 G, cap 4000 G"]
    fn two_items_of_the_same_type_both_count_toward_the_insurance_sum() {}

    #[test]
    #[ignore = "TODO: two sword damages against two insured swords -> each gets its own deductible"]
    fn each_damage_entry_of_a_repeated_item_type_gets_its_own_deductible() {}

    #[test]
    #[ignore = "TODO: two sword damages but only one sword insured -> Err; CLI exits non-zero"]
    fn more_damage_entries_than_insured_items_of_that_type_is_rejected() {}

    #[test]
    #[ignore = "TODO: amulet damaged when only a sword is insured -> Err; CLI exits non-zero"]
    fn a_damage_to_an_item_outside_the_policy_is_rejected() {}

    #[test]
    #[ignore = "TODO: damage with an unknown item type -> Err; CLI exits non-zero"]
    fn a_damage_with_an_unknown_item_type_is_rejected() {}

    #[test]
    #[ignore = "TODO: damage amount -200 -> Err; CLI exits non-zero"]
    fn a_negative_damage_amount_is_rejected() {}

    #[test]
    #[ignore = "TODO: scenario results array matches the steps array in length and order"]
    fn a_scenario_returns_one_result_per_step_in_order() {}

    #[test]
    #[ignore = "TODO: schema example scenario -> quote premium then claim payout and remainingCap"]
    fn the_schema_example_scenario_produces_a_quote_and_a_claim_result() {}

    #[test]
    #[ignore = "TODO: scenario JSON in -> {\"results\": [...]} JSON out with exactly the schema field names"]
    fn the_scenario_is_driven_by_the_documented_json_contract() {}
}

