pub struct Customer {
    years_with_mhpco: u32,
}

impl Customer {
    pub fn new(years_with_mhpco: u32) -> Self {
        Self { years_with_mhpco }
    }
}

pub enum ItemType {
    Sword,
}

pub struct Item {
    item_type: ItemType,
}

impl Item {
    pub fn new(item_type: ItemType) -> Self {
        Self { item_type }
    }
}

const PROCESSING_FEE: u64 = 5;
const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;

fn base_premium(item: &Item) -> f64 {
    match item.item_type {
        ItemType::Sword => 100.0,
    }
}

/// Premiums are rounded up: the MHPCO's favour is the larger amount.
fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
    amount.ceil() as u64
}

pub fn quote(_customer: &Customer, items: &[Item]) -> u64 {
    let policy_base: f64 = items.iter().map(base_premium).sum();
    let premium_before_fee = policy_base + policy_base * FIRST_INSURANCE_SURCHARGE;
    round_premium_in_mhpco_favour(premium_before_fee) + PROCESSING_FEE
}

#[cfg(test)]

