const PROCESSING_FEE: u64 = 5;
const FIRST_INSURANCE_SURCHARGE: f64 = 0.10;
/// Components -- for example runes and moonstones -- share one price-list row.
const COMPONENT_BASE_PREMIUM: f64 = 25.0;

fn base_premium(item: &Item) -> f64 {
    match item.item_type {
        ItemType::Sword => 100.0,
        ItemType::Amulet => 60.0,
        ItemType::Staff => 80.0,
        ItemType::Potion => 40.0,
        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
    }
}

/// Premiums are rounded up: the MHPCO's favour is the larger amount.
fn round_premium_in_mhpco_favour(amount: f64) -> u64 {
    amount.ceil() as u64
}

/// Policy-wide modifiers apply to the policy base premium, the sum of all
/// item base premiums. Every quoted item is treated as a first insurance.
fn apply_policy_modifiers(_customer: &Customer, policy_base: f64) -> f64 {
    policy_base + policy_base * FIRST_INSURANCE_SURCHARGE
}

pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
    let policy_base: f64 = items.iter().map(base_premium).sum();
    let premium_before_fee = apply_policy_modifiers(customer, policy_base);
    round_premium_in_mhpco_favour(premium_before_fee) + PROCESSING_FEE
}

