impl Damage {
    pub fn new(item_type: ItemType, amount: i64) -> Self {
        Self { item_type, amount }
    }

    /// What the MHPCO reimburses for this one damaged item, as an exact
    /// fraction: the share of the damage amount its clauses allow, less the
    /// deductible that applies once per damage event. No special clause applies
    /// yet, so the whole amount is reimbursed; the clauses that reduce this
    /// share read the damaged item's enchantment and material.
    fn reimbursement(&self) -> f64 {
        self.amount as f64 - DEDUCTIBLE_PER_DAMAGE
    }
}
    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
        let _ = &self.items;
        let reimbursed: f64 = damages.iter().map(Damage::reimbursement).sum();
        Ok(Settlement {
            payout: settled_payout(reimbursed),
        })
    }

