impl Policy {
    pub fn new(items: &[Item]) -> Self {
        Self {
            items: items.to_vec(),
        }
    }

    /// The insured item a reported damage refers to. Which of the policy's items
    /// answers for a damage is the MHPCO's coverage question, kept apart from how
    /// the damage is reimbursed: an incident reporting more damaged items of a
    /// type than the policy insures, or an item the policy never covered, is a
    /// coverage failure and not yet active behaviour.
    fn insured_item_for(&self, damage: &Damage) -> &Item {
        self.items
            .iter()
            .find(|item| item.item_type == damage.item_type)
            .expect("the damaged item is covered by this policy")
    }

    /// What the MHPCO reimburses for a whole incident, as an exact fraction: each
    /// damaged item reimbursed under the clauses of the insured item that answers
    /// for it. This is the incident-level amount the MHPCO recognises, before it
    /// is settled into the amount paid out.
    fn reimbursed_total(&self, damages: &[Damage]) -> f64 {
        damages
            .iter()
            .map(|damage| damage.reimbursement(self.insured_item_for(damage)))
            .sum()
    }

    /// The MHPCO settles an incident against this policy: it reimburses the
    /// incident under the policy's clauses, then settles that total into the
    /// amount it pays out.
    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, String> {
        Ok(Settlement {
            payout: settled_payout(self.reimbursed_total(damages)),
            remaining_cap: 0,
        })
    }
}

